text:
net copy_views

(seed) -pulse-> [emit] -pulse-> (out)
(lock) -permit-> [emit]
(out) -pulse-> [echo]
(lock) -permit-> [echo]
(requested) -job-> [lend]
(requested) -job-> [recall]
(lock) -permit-> [lend]
(lock) -permit-> [recall]
(lock) annotation fusion true
decorate (lock) beside

view laid position [emit] at {"x": 40, "y": 0}
view laid position (lock) at {"x": 0, "y": 0}
view laid position (lock)@[emit] relative [emit] + {"x": -10, "y": 0}
view laid position (out) relative (lock)@[emit] + {"x": 5, "y": 0}
view laid position (lock)@[echo] at {"x": 80, "y": 0}
view laid position (seed) relative (lock) + {"x": 1, "y": 2}
view laid position (lock)@[lend] at {"x": 10, "y": 1}
view laid position (lock)@[recall] at {"x": 10, "y": 1}
